/* Human / Agent view toggle.
   Every page has a plain-markdown twin at <path>.md (generated by
   scripts/build_agent.py). The pill at the bottom swaps the page for a
   readable rendering of that markdown, with copy / send-to-assistant actions.
   Mode lives in sessionStorage; ?view=agent|human deep-links into a mode. */
(function () {
  var KEY = "av-mode";
  var SITE = "https://scottchristensen.design";
  var root = document.documentElement;

  // ------------------------------------------------------------ paths
  function mdPathFor(p) {
    p = p.replace(/index\.html$/, "").replace(/\.html$/, "").replace(/\/+$/, "");
    return (p || "/index") + ".md";
  }
  function pagePathFor(md) {
    var p = md.replace(/^https?:\/\/[^/]+/, "").replace(/\.md$/, "");
    if (p === "/index") return "/";
    if (p.indexOf("/work/") === 0) return p + "/";
    return p + ".html";
  }
  var mdPath = mdPathFor(location.pathname);

  // ------------------------------------------------------------ state
  function getMode() {
    var q = new URLSearchParams(location.search).get("view");
    if (q === "agent" || q === "human") {
      try { sessionStorage.setItem(KEY, q); } catch (e) {}
      return q;
    }
    try { return sessionStorage.getItem(KEY) === "agent" ? "agent" : "human"; } catch (e) { return "human"; }
  }
  var mode = getMode();

  function track(name, params) {
    if (typeof window.gtag === "function") window.gtag("event", name, params);
  }

  // ------------------------------------------------------------ markdown
  function esc(s) {
    return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }
  function localize(href) {
    return href.indexOf(SITE) === 0 ? href.slice(SITE.length) || "/" : href;
  }
  function inline(s) {
    var codes = [];
    s = esc(s).replace(/`([^`]+)`/g, function (_, c) { codes.push(c); return "\u0000" + (codes.length - 1) + "\u0000"; });
    s = s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, function (_, text, href) {
      href = localize(href.replace(/&amp;/g, "&"));
      var ext = /^https?:|^mailto:/.test(href);
      return '<a href="' + esc(href) + '"' + (ext ? ' target="_blank" rel="noopener"' : "") + ">" + text + "</a>";
    });
    s = s.replace(/(^|[\s(])(https?:\/\/[^\s<)]+)/g, function (_, pre, url) {
      var href = localize(url.replace(/&amp;/g, "&"));
      return pre + '<a href="' + esc(href) + '"' + (/^https?:/.test(href) ? ' target="_blank" rel="noopener"' : "") + ">" + url + "</a>";
    });
    s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>").replace(/(^|[^*])\*([^*\s][^*]*)\*/g, "$1<em>$2</em>");
    return s.replace(/\u0000(\d+)\u0000/g, function (_, i) { return "<code>" + codes[i] + "</code>"; }).replace(/ {2}$/gm, "<br>");
  }
  function render(md) {
    var lines = md.replace(/\r/g, "").split("\n"), html = [], i = 0;
    while (i < lines.length) {
      var l = lines[i], m;
      if (/^```/.test(l)) {
        var code = [];
        for (i++; i < lines.length && !/^```/.test(lines[i]); i++) code.push(lines[i]);
        html.push("<pre><code>" + esc(code.join("\n")) + "</code></pre>"); i++;
      } else if ((m = /^(#{1,6})\s+(.*)$/.exec(l))) {
        html.push("<h" + m[1].length + ">" + inline(m[2]) + "</h" + m[1].length + ">"); i++;
      } else if (/^(-{3,}|\*{3,})\s*$/.test(l)) {
        html.push("<hr>"); i++;
      } else if (/^>\s?/.test(l)) {
        var q = [];
        for (; i < lines.length && /^>\s?/.test(lines[i]); i++) q.push(lines[i].replace(/^>\s?/, ""));
        html.push("<blockquote>" + inline(q.join(" ")) + "</blockquote>");
      } else if (/^\s*([-*]|\d+\.)\s+/.test(l)) {
        var ordered = /^\s*\d+\./.test(l), items = [];
        for (; i < lines.length && /^\s*([-*]|\d+\.)\s+/.test(lines[i]); i++) items.push("<li>" + inline(lines[i].replace(/^\s*([-*]|\d+\.)\s+/, "")) + "</li>");
        html.push((ordered ? "<ol>" : "<ul>") + items.join("") + (ordered ? "</ol>" : "</ul>"));
      } else if (!l.trim()) {
        i++;
      } else {
        var p = [];
        for (; i < lines.length && lines[i].trim() && !/^(#{1,6}\s|>|```|\s*([-*]|\d+\.)\s)/.test(lines[i]); i++) p.push(lines[i]);
        html.push("<p>" + inline(p.join("\n")) + "</p>");
      }
    }
    return html.join("\n");
  }

  // ------------------------------------------------------------ data
  var docText = null, docUrl = mdPath, pages = null;

  function fetchText(url) {
    return fetch(url).then(function (r) {
      var type = r.headers.get("content-type") || "";
      if (!r.ok || type.indexOf("text/html") !== -1) throw new Error("no doc");
      return r.text();
    });
  }
  function loadDoc() {
    return fetchText(mdPath).catch(function () { docUrl = "/llms.txt"; return fetchText("/llms.txt"); })
      .then(function (t) { docText = t; return t; });
  }
  function loadPages() {
    return fetchText("/llms.txt").then(function (t) {
      pages = [];
      t.replace(/^- \[([^\]]+)\]\(([^)]+\.md)\):\s*(.*)$/gm, function (_, title, url, summary) {
        pages.push({ title: title, md: url.replace(/^https?:\/\/[^/]+/, ""), summary: summary });
      });
      return pages;
    }).catch(function () { return (pages = []); });
  }

  // ------------------------------------------------------------ actions
  function copy(textOrPromise, btn) {
    var done = function () {
      var label = btn.querySelector("span") || btn, old = label.textContent;
      label.textContent = "Copied";
      setTimeout(function () { label.textContent = old; }, 1600);
    };
    var p;
    if (typeof textOrPromise === "string") p = navigator.clipboard.writeText(textOrPromise);
    else if (window.ClipboardItem) {
      // Keeps the user-gesture alive in Safari while the fetch resolves.
      p = navigator.clipboard.write([new ClipboardItem({ "text/plain": textOrPromise.then(function (t) { return new Blob([t], { type: "text/plain" }); }) })]);
    } else p = textOrPromise.then(function (t) { return navigator.clipboard.writeText(t); });
    p.then(done).catch(function () { (btn.querySelector("span") || btn).textContent = "Copy failed"; });
  }
  function prompt() {
    var url = SITE + docUrl, max = 6500, body = docText || "";
    if (body.length > max) body = body.slice(0, max) + "\n\n[truncated; full doc at " + url + "]";
    return "Here is the agent version of a page from Scott Christensen's portfolio (" + url + "). Read it, then help me with…\n\n" + body;
  }
  var SEND = {
    claude: "https://claude.ai/new?q=",
    chatgpt: "https://chatgpt.com/?q=",
    gemini: "https://www.google.com/search?udm=50&q=" // Gemini app has no prefill param
  };

  // ------------------------------------------------------------ UI

  // Brand marks (Simple Icons) for the send-to links; line icons for the rest.
  var BRAND = {"chatgpt": "M22.2819 9.8211a5.9847 5.9847 0 0 0-.5157-4.9108 6.0462 6.0462 0 0 0-6.5098-2.9A6.0651 6.0651 0 0 0 4.9807 4.1818a5.9847 5.9847 0 0 0-3.9977 2.9 6.0462 6.0462 0 0 0 .7427 7.0966 5.98 5.98 0 0 0 .511 4.9107 6.051 6.051 0 0 0 6.5146 2.9001A5.9847 5.9847 0 0 0 13.2599 24a6.0557 6.0557 0 0 0 5.7718-4.2058 5.9894 5.9894 0 0 0 3.9977-2.9001 6.0557 6.0557 0 0 0-.7475-7.0729zm-9.022 12.6081a4.4755 4.4755 0 0 1-2.8764-1.0408l.1419-.0804 4.7783-2.7582a.7948.7948 0 0 0 .3927-.6813v-6.7369l2.02 1.1686a.071.071 0 0 1 .038.052v5.5826a4.504 4.504 0 0 1-4.4945 4.4944zm-9.6607-4.1254a4.4708 4.4708 0 0 1-.5346-3.0137l.142.0852 4.783 2.7582a.7712.7712 0 0 0 .7806 0l5.8428-3.3685v2.3324a.0804.0804 0 0 1-.0332.0615L9.74 19.9502a4.4992 4.4992 0 0 1-6.1408-1.6464zM2.3408 7.8956a4.485 4.485 0 0 1 2.3655-1.9728V11.6a.7664.7664 0 0 0 .3879.6765l5.8144 3.3543-2.0201 1.1685a.0757.0757 0 0 1-.071 0l-4.8303-2.7865A4.504 4.504 0 0 1 2.3408 7.872zm16.5963 3.8558L13.1038 8.364 15.1192 7.2a.0757.0757 0 0 1 .071 0l4.8303 2.7913a4.4944 4.4944 0 0 1-.6765 8.1042v-5.6772a.79.79 0 0 0-.407-.667zm2.0107-3.0231l-.142-.0852-4.7735-2.7818a.7759.7759 0 0 0-.7854 0L9.409 9.2297V6.8974a.0662.0662 0 0 1 .0284-.0615l4.8303-2.7866a4.4992 4.4992 0 0 1 6.6802 4.66zM8.3065 12.863l-2.02-1.1638a.0804.0804 0 0 1-.038-.0567V6.0742a4.4992 4.4992 0 0 1 7.3757-3.4537l-.142.0805L8.704 5.459a.7948.7948 0 0 0-.3927.6813zm1.0976-2.3654l2.602-1.4998 2.6069 1.4998v2.9994l-2.5974 1.4997-2.6067-1.4997Z", "claude": "m4.7144 15.9555 4.7174-2.6471.079-.2307-.079-.1275h-.2307l-.7893-.0486-2.6956-.0729-2.3375-.0971-2.2646-.1214-.5707-.1215-.5343-.7042.0546-.3522.4797-.3218.686.0608 1.5179.1032 2.2767.1578 1.6514.0972 2.4468.255h.3886l.0546-.1579-.1336-.0971-.1032-.0972L6.973 9.8356l-2.55-1.6879-1.3356-.9714-.7225-.4918-.3643-.4614-.1578-1.0078.6557-.7225.8803.0607.2246.0607.8925.686 1.9064 1.4754 2.4893 1.8336.3643.3035.1457-.1032.0182-.0728-.164-.2733-1.3539-2.4467-1.445-2.4893-.6435-1.032-.17-.6194c-.0607-.255-.1032-.4674-.1032-.7285L6.287.1335 6.6997 0l.9957.1336.419.3642.6192 1.4147 1.0018 2.2282 1.5543 3.0296.4553.8985.2429.8318.091.255h.1579v-.1457l.1275-1.706.2368-2.0947.2307-2.6957.0789-.7589.3764-.9107.7468-.4918.5828.2793.4797.686-.0668.4433-.2853 1.8517-.5586 2.9021-.3643 1.9429h.2125l.2429-.2429.9835-1.3053 1.6514-2.0643.7286-.8196.85-.9046.5464-.4311h1.0321l.759 1.1293-.34 1.1657-1.0625 1.3478-.8804 1.1414-1.2628 1.7-.7893 1.36.0729.1093.1882-.0183 2.8535-.607 1.5421-.2794 1.8396-.3157.8318.3886.091.3946-.3278.8075-1.967.4857-2.3072.4614-3.4364.8136-.0425.0304.0486.0607 1.5482.1457.6618.0364h1.621l3.0175.2247.7892.522.4736.6376-.079.4857-1.2142.6193-1.6393-.3886-3.825-.9107-1.3113-.3279h-.1822v.1093l1.0929 1.0686 2.0035 1.8092 2.5075 2.3314.1275.5768-.3218.4554-.34-.0486-2.2039-1.6575-.85-.7468-1.9246-1.621h-.1275v.17l.4432.6496 2.3436 3.5214.1214 1.0807-.17.3521-.6071.2125-.6679-.1214-1.3721-1.9246L14.38 17.959l-1.1414-1.9428-.1397.079-.674 7.2552-.3156.3703-.7286.2793-.6071-.4614-.3218-.7468.3218-1.4753.3886-1.9246.3157-1.53.2853-1.9004.17-.6314-.0121-.0425-.1397.0182-1.4328 1.9672-2.1796 2.9446-1.7243 1.8456-.4128.164-.7164-.3704.0667-.6618.4008-.5889 2.386-3.0357 1.4389-1.882.929-1.0868-.0062-.1579h-.0546l-6.3385 4.1164-1.1293.1457-.4857-.4554.0608-.7467.2307-.2429 1.9064-1.3114Z", "gemini": "M11.04 19.32Q12 21.51 12 24q0-2.49.93-4.68.96-2.19 2.58-3.81t3.81-2.55Q21.51 12 24 12q-2.49 0-4.68-.93a12.3 12.3 0 0 1-3.81-2.58 12.3 12.3 0 0 1-2.58-3.81Q12 2.49 12 0q0 2.49-.96 4.68-.93 2.19-2.55 3.81a12.3 12.3 0 0 1-3.81 2.58Q2.49 12 0 12q2.49 0 4.68.96 2.19.93 3.81 2.55t2.55 3.81"};
  function brandIcon(k) { return '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="' + BRAND[k] + '"/></svg>'; }
  function lineIcon(d) { return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + d + "</svg>"; }
  var ICON = {
    copy: lineIcon('<rect x="9" y="9" width="12" height="12" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>'),
    download: lineIcon('<path d="M12 3v12M7 10l5 5 5-5M5 21h14"/>'),
    external: lineIcon('<path d="M15 3h6v6M10 14 21 3M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>'),
    file: lineIcon('<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h6"/>')
  };

  var dock, thumb, btnHuman, btnAgent, overlay, built = false;

  function el(tag, attrs, html) {
    var n = document.createElement(tag);
    for (var k in attrs || {}) n.setAttribute(k, attrs[k]);
    if (html != null) n.innerHTML = html;
    return n;
  }

  function buildDock() {
    dock = el("div", { "class": "av-dock", role: "group", "aria-label": "View as" });
    thumb = el("span", { "class": "av-thumb", "aria-hidden": "true" });
    btnHuman = el("button", { type: "button", "class": "av-seg" }, "<span>Human</span>");
    btnAgent = el("button", { type: "button", "class": "av-seg" }, "<span>Agent</span>");
    btnHuman.addEventListener("click", function () { setMode("human", true); });
    btnAgent.addEventListener("click", function () { setMode("agent", true); });
    dock.appendChild(thumb); dock.appendChild(btnHuman); dock.appendChild(btnAgent);
    document.body.appendChild(dock);
    window.addEventListener("resize", positionThumb);
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(positionThumb);
  }

  function positionThumb() {
    var b = mode === "agent" ? btnAgent : btnHuman;
    thumb.style.width = b.offsetWidth + "px";
    thumb.style.transform = "translateX(" + b.offsetLeft + "px)";
    btnHuman.setAttribute("aria-pressed", String(mode === "human"));
    btnAgent.setAttribute("aria-pressed", String(mode === "agent"));
  }

  function action(icon, label, cls, onClick, href) {
    var a = el(href ? "a" : "button", href ? { "class": "av-act " + cls, href: href, target: "_blank", rel: "noopener" } : { type: "button", "class": "av-act " + cls }, icon + "<span>" + label + "</span>");
    a.addEventListener("click", function (e) { onClick && onClick(e, a); });
    return a;
  }

  function buildOverlay() {
    overlay = el("div", { "class": "av-overlay", role: "dialog", "aria-modal": "true", "aria-label": "Agent view" });
    overlay.innerHTML =
      '<div class="av-bar"><button type="button" class="av-back">← Back to page</button>' +
      '<a class="av-wordmark" href="/?view=agent">Scott Christensen</a>' +
      '<span class="av-path"></span></div>' +
      '<div class="av-layout"><main class="av-main"><p class="av-label">Agent view · plain markdown</p>' +
      '<article class="av-doc">Loading…</article><section class="av-others"></section></main>' +
      '<aside class="av-rail" aria-label="Actions"></aside></div>';
    overlay.querySelector(".av-back").addEventListener("click", function () { setMode("human", true); });
    document.body.appendChild(overlay);
  }

  function log(name) { track("agent_doc_action", { action: name, page_path: location.pathname }); }

  function fillOverlay() {
    if (built) return;
    built = true;
    var rail = overlay.querySelector(".av-rail");
    rail.appendChild(action(ICON.copy, "Copy .md", "is-primary", function (e, b) { log("copy_md"); copy(docText || "", b); }));
    [["chatgpt", "ChatGPT"], ["claude", "Claude"], ["gemini", "Gemini"]].forEach(function (x) {
      rail.appendChild(action(brandIcon(x[0]), "Send to " + x[1], "", function (e, a) { a.href = SEND[x[0]] + encodeURIComponent(prompt()); log("send_" + x[0]); }, "#"));
    });
    rail.appendChild(action(ICON.download, "Download .md", "", function () {
      log("download_md");
      var a = el("a", { href: URL.createObjectURL(new Blob([docText || ""], { type: "text/markdown" })), download: docUrl.split("/").pop() });
      document.body.appendChild(a); a.click(); a.remove();
    }));
    rail.appendChild(action(ICON.external, "Open raw .md", "av-raw", function () { log("open_raw"); }, docUrl));
    rail.appendChild(el("hr"));
    rail.appendChild(el("h3", {}, "Whole site"));
    rail.appendChild(action(ICON.copy, "Copy whole site", "", function (e, b) { log("copy_full"); copy(fetchText("/llms-full.txt"), b); }));
    rail.appendChild(action(ICON.file, "llms-full.txt", "", function () { log("open_llms_full"); }, "/llms-full.txt"));
    rail.appendChild(action(ICON.file, "llms.txt index", "", function () { log("open_llms"); }, "/llms.txt"));

    loadDoc().then(function (t) {
      overlay.querySelector(".av-path").textContent = docUrl;
      overlay.querySelector(".av-raw").setAttribute("href", docUrl);
      overlay.querySelector(".av-doc").innerHTML = render(t);
    }).catch(function () {
      overlay.querySelector(".av-doc").textContent = "Couldn't load the markdown for this page.";
    });

    loadPages().then(function (list) {
      var others = list.filter(function (p) { return p.md !== mdPath; });
      if (!others.length) return;
      var items = others.map(function (p) {
        var page = pagePathFor(p.md);
        return '<li><a class="av-other-title" href="' + esc(page) + '?view=agent">' + esc(p.title) + "</a>" +
          "<p>" + esc(p.summary) + "</p>" +
          '<div class="av-mono">' + esc(SITE + page) + ' · <a href="' + esc(p.md) + '" target="_blank" rel="noopener">' + esc(p.md) + "</a></div></li>";
      }).join("");
      overlay.querySelector(".av-others").innerHTML = "<h2>Everything else on this site</h2><ul>" + items + "</ul>";
    });
  }

  function onKey(e) { if (e.key === "Escape") setMode("human", true); }

  function setMode(next, user) {
    mode = next;
    try { sessionStorage.setItem(KEY, mode); } catch (e) {}
    positionThumb();
    if (mode === "agent") {
      fillOverlay();
      overlay.scrollTop = 0;
      overlay.classList.add("is-open");
      root.classList.add("av-lock");
      document.addEventListener("keydown", onKey);
    } else {
      overlay.classList.remove("is-open");
      root.classList.remove("av-lock");
      document.removeEventListener("keydown", onKey);
    }
    root.classList.remove("av-pre");
    if (user) track("view_mode_toggled", { mode: mode, page_path: location.pathname });
  }

  function init() {
    buildDock();
    buildOverlay();
    // Clean ?view= out of the URL once it has been applied.
    var url = new URL(location.href);
    if (url.searchParams.has("view")) {
      url.searchParams.delete("view");
      history.replaceState(null, "", url.pathname + url.search + url.hash);
    }
    if (mode === "agent") {
      overlay.style.transition = "none"; // no fade when landing directly in agent view
      setMode("agent", false);
      requestAnimationFrame(function () { overlay.style.transition = ""; });
    } else {
      setMode("human", false);
    }
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();
